  margin: 0.75rem 0 1rem;
  border: 1px solid var(--border-default-grey, #ddd);
  border-radius: 0.25rem;
  overflow: hidden;
  background: var(--background-default-grey, #fff);
  box-shadow: var(--raised-shadow, 0 2px 6px rgba(0, 0, 18, 0.16));
}

/* Champ source masqué (hide) — !important pour gagner sur .fr-input / display auteur */
.ec-geometry-editor-source--hidden {
  display: none !important;
}

.ec-geometry-editor__map {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

/* Colonne d’outils dans la carte (positionnée via tools-root) */
.ec-geometry-editor__tools-root {
  /* Vars aussi hors .ec-geometry-editor (SketchControl carte principale) */
  --ec-geom-btn-size: var(--ec-widget-btn-size, 48px);
  --ec-geom-btn-gap: var(--ec-widget-gap, 8px);
  --ec-geom-btn-padding: var(--ec-widget-btn-padding, 4px);
  --ec-geom-btn-radius: var(--ec-widget-btn-radius, 4px);
  position: absolute;
  top: var(--ec-geom-btn-gap);
  left: var(--ec-geom-btn-gap);
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 0;
  margin: 0;
  padding: 0;
  /*
   * OpenLayers Control : pointer-events inline auto sur l’élément —
   * !important pour que la zone transparente laisse passer clics / pan carte.
   */
  pointer-events: none !important;
  overflow: visible;
  width: var(--ec-geom-btn-size);
  max-width: var(--ec-geom-btn-size);
  /* Limite à la hauteur carte → scroll de la barre outils si besoin */
  max-height: calc(100% - 2 * var(--ec-geom-btn-gap));
  min-height: 0;
}

.ec-geometry-editor__tools-root > .ec-geometry-editor__tool--tools-toggle {
  pointer-events: auto;
  flex-shrink: 0;
}

/* Seuls les boutons capturent les clics (pas la zone infobulle transparente) */
.ec-geometry-editor__tools-root > .ec-geometry-editor__toolbar-cluster {
  pointer-events: none;
  flex: 1 1 auto;
  min-height: 0;
  min-width: 0;
  max-width: 100%;
  /* visible : barre modification en position absolue à côté du bouton Modifier */
  overflow: visible;
}

.ec-geometry-editor__tools-root > .ec-geometry-editor__toolbar {
  pointer-events: none;
}

.ec-geometry-editor__toolbar > .ec-geometry-editor__tool {
  pointer-events: auto;
}

/*
 * Infobulles / barre modification en overflow — marge négative :
 * la boîte layout du croquis reste la colonne 48px.
 */
.ec-geometry-editor > .ec-geometry-editor__tools-root > .ec-geometry-editor__toolbar-cluster {
  margin-inline-end: calc(-1 * var(--ec-geom-tooltip-space));
}

.ec-geometry-editor
  > .ec-geometry-editor__tools-root[data-corner='top-right']
  > .ec-geometry-editor__toolbar-cluster,
.ec-geometry-editor
  > .ec-geometry-editor__tools-root[data-corner='bottom-right']
  > .ec-geometry-editor__toolbar-cluster {
  margin-inline-end: 0;
  margin-inline-start: calc(-1 * var(--ec-geom-tooltip-space));
}

.ec-geometry-editor__tools-root[data-corner] {
  gap: var(--ec-geom-btn-gap);
}

.ec-geometry-editor__tools-root[data-corner='top-left'] {
  top: var(--ec-geom-btn-gap);
  left: var(--ec-geom-btn-gap);
  right: auto;
  bottom: auto;
  flex-direction: column;
}

.ec-geometry-editor__tools-root[data-corner='top-right'] {
  top: var(--ec-geom-btn-gap);
  right: var(--ec-geom-btn-gap);
  left: auto;
  bottom: auto;
  flex-direction: column;
}

.ec-geometry-editor__tools-root[data-corner='bottom-left'] {
  top: auto;
  left: var(--ec-geom-btn-gap);
  right: auto;
  bottom: var(--ec-geom-btn-gap);
  flex-direction: column-reverse;
}

.ec-geometry-editor__tools-root[data-corner='bottom-right'] {
  top: auto;
  right: var(--ec-geom-btn-gap);
  left: auto;
  bottom: var(--ec-geom-btn-gap);
  flex-direction: column-reverse;
}

.ec-geometry-editor__toolbar {
  --ec-geom-tooltip-space: 12.5rem;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 0;
  /* Largeur visuelle = bouton ; padding = place pour l’infobulle (évite le clip overflow) */
  box-sizing: border-box;
  width: calc(var(--ec-geom-btn-size) + var(--ec-geom-tooltip-space));
  margin: 0;
  padding: 0;
  padding-inline-end: var(--ec-geom-tooltip-space);
  /* Zone padding transparente : clics / scroll carte passent au travers */
  pointer-events: none;
  border: none;
  border-radius: var(--ec-geom-btn-radius);
  /* Fond / ombre uniquement sur la colonne boutons */
  background: linear-gradient(
    to right,
    var(--background-default-grey, #fff) 0,
    var(--background-default-grey, #fff) var(--ec-geom-btn-size),
    transparent var(--ec-geom-btn-size)
  );
  box-shadow: none;
  filter: drop-shadow(0 2px 6px rgba(0, 0, 18, 0.16));
  /* Scroll si la barre dépasse la carte (pas le bouton toolsToggle) */
  flex: 1 1 auto;
  min-height: 0;
  max-height: 100%;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.ec-geometry-editor__toolbar::-webkit-scrollbar {
  width: 0;
  height: 0;
  display: none;
}

/* Coins droits : infobulle à gauche → padding de l’autre côté */
.ec-geometry-editor__tools-root[data-corner='top-right'] .ec-geometry-editor__toolbar,
.ec-geometry-editor__tools-root[data-corner='bottom-right'] .ec-geometry-editor__toolbar {
  padding-inline-end: 0;
  padding-inline-start: var(--ec-geom-tooltip-space);
  background: linear-gradient(
    to left,
    var(--background-default-grey, #fff) 0,
    var(--background-default-grey, #fff) var(--ec-geom-btn-size),
    transparent var(--ec-geom-btn-size)
  );
  align-items: flex-end;
}

.ec-geometry-editor__tools-root[data-corner] .ec-geometry-editor__toolbar-cluster {
  flex: 1 1 auto;
  min-height: 0;
  max-height: calc(100% - var(--ec-geom-btn-size) - var(--ec-geom-btn-gap));
}

.ec-geometry-editor__tools-root[data-corner] .ec-geometry-editor__toolbar {
  flex: 1 1 auto;
  min-height: 0;
  max-height: 100%;
}

.ec-geometry-editor__toolbar[hidden] {
  display: none !important;
}

.ec-geometry-editor__toolbar-cluster[hidden] {
  display: none !important;
}

/* toolsToggle : barre dessin masquée tant que le bouton menu n’a pas ouvert le panneau */
.ec-geometry-editor__tools-root[data-corner]:not(.is-open) > .ec-geometry-editor__toolbar-cluster {
  display: none !important;
}

/* Barre dessin + barre modification (côte à côte, vers l’intérieur carte) */
.ec-geometry-editor__toolbar-cluster {
  position: relative;
  display: flex;
  flex-direction: row;
  align-items: stretch;
  gap: 0;
  min-width: 0;
  min-height: 0;
  max-height: 100%;
  overflow: visible;
}

.ec-geometry-editor__tools-root[data-corner='top-right'] .ec-geometry-editor__toolbar-cluster,
.ec-geometry-editor__tools-root[data-corner='bottom-right'] .ec-geometry-editor__toolbar-cluster {
  flex-direction: row-reverse;
}

.ec-geometry-editor__toolbar-cluster--stack {
  flex-direction: column;
}

.ec-geometry-editor__tools-root[data-corner='top-right']
  .ec-geometry-editor__toolbar-cluster--stack,
.ec-geometry-editor__tools-root[data-corner='bottom-right']
  .ec-geometry-editor__toolbar-cluster--stack {
  flex-direction: column-reverse;
}

.ec-geometry-editor__modify-toolbar[hidden] {
  display: none !important;
}

.ec-geometry-editor__modify-toolbar {
  position: absolute;
  z-index: 6;
  display: flex;
  flex-shrink: 0;
  gap: 0;
  pointer-events: auto;
  background: var(--background-default-grey, #fff);
  border-radius: var(--ec-geom-btn-radius);
  filter: drop-shadow(0 2px 6px rgba(0, 0, 18, 0.16));
}

.ec-geometry-editor__modify-toolbar > .ec-geometry-editor__tool {
  pointer-events: auto;
  overflow: visible;
}

.ec-geometry-editor__modify-toolbar--row {
  flex-direction: row;
}

.ec-geometry-editor__modify-toolbar--column {
  flex-direction: column;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
}

.ec-geometry-editor__modify-toolbar .ec-geometry-editor__tool {
  border-radius: 0;
}

.ec-geometry-editor__modify-toolbar .ec-geometry-editor__tool[hidden] {
  display: none !important;
}

.ec-geometry-editor__modify-toolbar--row .ec-geometry-editor__tool:first-child {
  border-radius: var(--ec-geom-btn-radius) 0 0 var(--ec-geom-btn-radius);
}

.ec-geometry-editor__modify-toolbar--row .ec-geometry-editor__tool:last-child {
  border-radius: 0 var(--ec-geom-btn-radius) var(--ec-geom-btn-radius) 0;
}

.ec-geometry-editor__modify-toolbar--column .ec-geometry-editor__tool:first-child {
  border-radius: var(--ec-geom-btn-radius) var(--ec-geom-btn-radius) 0 0;
}

.ec-geometry-editor__modify-toolbar--column .ec-geometry-editor__tool:last-child {
  border-radius: 0 0 var(--ec-geom-btn-radius) var(--ec-geom-btn-radius);
}

.ec-geometry-editor__tool--tools-toggle {
  border-radius: var(--ec-geom-btn-radius);
  box-shadow: var(--raised-shadow, 0 2px 6px rgba(0, 0, 18, 0.16));
  /* Infobulle hors de la colonne étroite */
  overflow: visible;
}

.ec-geometry-editor__tool {
  box-sizing: border-box;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--ec-geom-btn-size) !important;
  height: var(--ec-geom-btn-size) !important;
  min-width: var(--ec-geom-btn-size);
  min-height: var(--ec-geom-btn-size);
  margin: 0 !important;
  padding: 4px !important;
  border: none !important;
  border-radius: 0;
  outline: none;
  background-color: var(--background-default-grey, #fff);
  color: var(--text-action-high-blue-france, #000091);
  cursor: pointer;
  transition: background-color 300ms;
}

.ec-geometry-editor__toolbar > .ec-geometry-editor__tool:first-child {
  border-radius: var(--ec-geom-btn-radius) var(--ec-geom-btn-radius) 0 0;
}

.ec-geometry-editor__toolbar > .ec-geometry-editor__tool:last-child {
  border-radius: 0 0 var(--ec-geom-btn-radius) var(--ec-geom-btn-radius);
}

.ec-geometry-editor__toolbar > .ec-geometry-editor__tool:only-child {
  border-radius: var(--ec-geom-btn-radius);
}

/* Coins arrondis même avec séparateurs intercalés */
.ec-geometry-editor__toolbar > .ec-geometry-editor__tool:first-of-type {
  border-radius: var(--ec-geom-btn-radius) var(--ec-geom-btn-radius) 0 0;
}

.ec-geometry-editor__toolbar > .ec-geometry-editor__tool:last-of-type {
  border-radius: 0 0 var(--ec-geom-btn-radius) var(--ec-geom-btn-radius);
}

.ec-geometry-editor__toolbar > .ec-geometry-editor__tool:first-of-type:last-of-type {
  border-radius: var(--ec-geom-btn-radius);
}

/* Séparateur entre groupes d’outils */
.ec-geometry-editor__toolbar-sep {
  box-sizing: border-box;
  flex: 0 0 auto;
  width: var(--ec-geom-btn-size);
  height: 9px;
  margin: 0;
  padding: 4px var(--ec-geom-btn-padding);
  background-color: var(--background-default-grey, #fff);
  pointer-events: none;
}

.ec-geometry-editor__toolbar-sep::before {
  content: '';
  display: block;
  height: 1px;
  background-color: var(--border-default-grey, #ddd);
}

.ec-geometry-editor__tool:hover,
.ec-geometry-editor__tool:focus-visible {
  background-color: var(--hover-tint, #e3e3fd);
  outline: none;
}

.ec-geometry-editor__tool.is-active,
.ec-geometry-editor__tool[aria-pressed='true'] {
  background-color: var(--background-open-blue-france, #e3e3fd);
  color: var(--text-action-high-blue-france, #000091);
}

/* Pictogrammes Remix Icon (`<i class="ri-… ec-geometry-editor__tool-icon">`) */
.ec-geometry-editor__tool-icon {
  font-size: 1.5rem;
  line-height: 1;
  pointer-events: none;
}

/* Badge état enregistrement (haut-gauche de l’icône) */
.ec-geometry-editor__tool-badge {
  position: absolute;
  top: 2px;
  left: 2px;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 0.85rem;
  height: 0.85rem;
  border-radius: 50%;
  background-color: var(--background-default-grey, #fff);
  pointer-events: none;
}

.ec-geometry-editor__tool-badge i {
  font-size: 0.75rem;
  line-height: 1;
}

.ec-geometry-editor__tool--save-saved .ec-geometry-editor__tool-badge {
  color: var(--success-425-625, #18753c);
}

.ec-geometry-editor__tool--save-dirty .ec-geometry-editor__tool-badge {
  color: var(--warning-425-625, #b34000);
}

.ec-geometry-editor__tool:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.ec-sketch-text-popup,
.ec-sketch-style-popup {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  min-width: 14rem;
  max-width: min(20rem, calc(100vw - 1rem));
  padding: 0.75rem;
  background: var(--background-default-grey, #fff);
  border: 1px solid var(--border-default-grey, #ddd);
  box-shadow: var(--overlap-shadow, 0 2px 8px rgba(0, 0, 18, 0.16));
  font-size: 0.875rem;
  box-sizing: border-box;
}

/* Overlay OL (bottom-center) — appendice centré */
.ec-sketch-style-popup {
  position: relative;
  overflow: visible;
  margin-bottom: 17px;
}

.ec-sketch-style-popup__scroll {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  max-height: 265px;
  overflow: auto;
  overscroll-behavior: contain;
}

/* Appendice vers le bas (popup au-dessus du point) */
.ec-sketch-style-popup::before {
  content: '';
  position: absolute;
  border-top: 16px solid var(--border-default-grey, #ddd);
  border-right: 15px solid transparent;
  border-left: 15px solid transparent;
  bottom: -17px;
  left: 50%;
  margin-left: -15px;
  pointer-events: none;
}

.ec-sketch-style-popup::after {
  content: '';
  position: absolute;
  border-top: 15px solid var(--background-default-grey, #fff);
  border-right: 14px solid transparent;
  border-left: 14px solid transparent;
  bottom: -15px;
  left: 50%;
  margin-left: -14px;
  pointer-events: none;
}

.ec-sketch-style-popup__advanced-toggle {
  align-self: flex-start;
  margin: 0;
  padding: 0.15rem 0;
  min-height: auto;
}

.ec-sketch-style-popup__fields--advanced {
  padding-top: 0.25rem;
  border-top: 1px solid var(--border-default-grey, #eee);
}

/* display:flex sur __fields écrase sinon l’attribut HTML hidden */
.ec-sketch-style-popup__fields--advanced[hidden] {
  display: none !important;
}

/* Color picker croquis */
.ec-sketch-color {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.ec-sketch-color__label {
  font-size: 0.75rem;
  color: var(--text-mention-grey, #666);
}

.ec-sketch-color__swatch {
  box-sizing: border-box;
  width: 100%;
  height: 2rem;
  padding: 0;
  border: 1px solid var(--border-default-grey, #ddd);
  border-radius: 0.25rem;
  cursor: pointer;
  background-color: transparent;
}

.ec-sketch-color__swatch:hover {
  cursor: pointer;
  outline: 2px solid var(--border-action-high-blue-france, #000091);
  outline-offset: 1px;
}

.ec-sketch-color__hue-native {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
  pointer-events: none;
}

.ec-sketch-color__hex-field,
.ec-sketch-color__alpha-field {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  margin: 0;
}

.ec-sketch-color__hex {
  width: 100%;
  font-family: ui-monospace, monospace;
  font-size: 0.8125rem;
}

.ec-sketch-color__alpha {
  width: 100%;
  accent-color: var(--background-action-high-blue-france, #000091);
  cursor: pointer;
}

.ec-sketch-text-popup[hidden],
.ec-sketch-style-popup[hidden] {
  display: none !important;
}

.ec-sketch-text-popup__field,
.ec-sketch-style-popup__field {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.ec-sketch-text-popup__field[hidden],
.ec-sketch-style-popup__field[hidden] {
  display: none !important;
}

.ec-sketch-style-popup__field.is-disabled {
  opacity: 0.45;
  pointer-events: none;
}

.ec-sketch-style-popup__field--check {
  flex-direction: row;
  align-items: center;
  gap: 0.5rem;
}

.ec-sketch-style-popup__field--check span {
  color: inherit;
  font-size: 0.875rem;
}

.ec-sketch-text-popup__field span,
.ec-sketch-style-popup__field span {
  font-size: 0.75rem;
  color: var(--text-mention-grey, #666);
}

.ec-sketch-text-popup__field--rotation,
.ec-sketch-style-popup__field--rotation,
.ec-sketch-style-popup__field--range {
  gap: 0.35rem;
}

.ec-sketch-text-popup__rotation,
.ec-sketch-style-popup__field--rotation input[type='range'],
.ec-sketch-style-popup__field--range input[type='range'] {
  width: 100%;
  accent-color: var(--background-action-high-blue-france, #000091);
}

.ec-sketch-text-popup__rotation-value,
.ec-sketch-style-popup__field--rotation output,
.ec-sketch-style-popup__field--range output {
  font: inherit;
}

.ec-sketch-text-popup__actions,
.ec-sketch-style-popup__actions {
  display: flex;
  gap: 0.5rem;
  justify-content: flex-end;
}

.ec-sketch-style-popup__fields {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

/* Popup mesure — même forme que localisation geopf (GPSearchPopup) */
.ec-sketch-measure-popup.GPSearchPopup,
.ec-sketch-measure-popup {
  display: flex;
  position: relative;
  align-items: center;
  justify-content: space-between;
  flex-wrap: nowrap;
  gap: 12px;
  width: max-content;
  min-width: 12rem;
  max-width: 288px;
  bottom: 17px;
  padding: 0.75rem;
  border: 1px solid var(--border-default-grey, #ddd);
  box-shadow: var(--overlap-shadow, 0 2px 8px rgba(0, 0, 18, 0.16));
  background-color: var(--background-default-grey, #fff);
  font-size: 0.75em;
  white-space: nowrap;
}

.ec-sketch-measure-popup::before {
  content: '';
  position: absolute;
  border-top: 16px solid var(--border-default-grey, #ddd);
  border-right: 15px solid transparent;
  border-left: 15px solid transparent;
  bottom: -17px;
  margin-left: -15px;
  left: 50%;
}

.ec-sketch-measure-popup::after {
  content: '';
  position: absolute;
  border-top: 15px solid var(--background-default-grey, #fff);
  border-right: 14px solid transparent;
  border-left: 14px solid transparent;
  bottom: -15px;
  margin-left: -14px;
  left: 50%;
}

.ec-sketch-measure-popup .GPPopupContent,
.ec-sketch-measure-popup__content {
  line-height: 1.25rem;
  font-weight: 700;
}

.ec-sketch-measure-popup .GPButtonGroups {
  display: flex;
  flex-direction: row-reverse;
  flex: 0 0 auto;
  align-items: center;
  gap: 0.25rem;
}

.ec-sketch-export-dialog {
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: 20;
  box-sizing: border-box;
  width: min(18rem, calc(100% - 2rem));
  padding: 0.75rem;
  background: var(--background-default-grey, #fff);
  border: 1px solid var(--border-default-grey, #ddd);
  border-radius: 0.25rem;
  box-shadow: var(--raised-shadow, 0 2px 6px rgba(0, 0, 18, 0.16));
  transform: translate(-50%, -50%);
}

.ec-sketch-export-dialog[hidden] {
  display: none !important;
}

.ec-sketch-export-dialog__title {
  margin: 0 0 0.75rem;
  font-size: 0.875rem;
  font-weight: 700;
}

.ec-sketch-export-dialog__field {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  margin-bottom: 0.75rem;
  font-size: 0.75rem;
}

.ec-sketch-export-dialog__field select {
  box-sizing: border-box;
  width: 100%;
  padding: 0.35rem 0.5rem;
  border: 1px solid var(--border-default-grey, #ddd);
  border-radius: 0.25rem;
  font: inherit;
}

.ec-sketch-export-dialog__actions {
  display: flex;
  gap: 0.5rem;
  justify-content: flex-end;
}

/*
 * Infobulles — même rendu que geopf `.gpf-btn-icon[aria-label]:hover::before`
 * (zoom, territoire, minimap, plein écran). Pictos outils = Remix Icon dans le bouton.
 *
 * Position : `left: 100%` / `right: 100%` (relatif au bouton), pas
 * `translate(100%)` (relatif à la largeur de la bulle → écart variable selon le libellé).
 */
.ec-geometry-editor__tool[aria-label]:hover::before,
.ec-geometry-editor__tool[aria-label]:focus-visible::before {
  content: attr(aria-label);
  position: absolute;
  top: var(--ec-geom-btn-padding);
  left: 100%;
  right: auto;
  z-index: 2000;
  width: fit-content;
  padding: 0.5rem 0.5rem 0.5rem 1.25rem;
  color: var(--text-default-grey, #161616);
  font-size: 0.75rem;
  line-height: 1.25;
  white-space: nowrap;
  pointer-events: none;
  background-repeat: no-repeat;
  background-position:
    0.125rem 50%,
    0 50%,
    0.375rem 100%,
    0.375rem 100%;
  background-size:
    0.375rem 0.5rem,
    0.375rem 0.5rem,
