  display: flex;
}

.ec-tab-panels__panel-body {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  padding: 1rem 1.25rem 1.5rem;
}

/*
 * Panneau latéral : pas de bordure / contour au survol ou au focus (OL, DSFR, navigateur).
 * Le soulignement de l’onglet catalogue actif est rétabli plus bas.
 */
.ec-tab-panels.ol-control .ec-tab-panels__panel-body button:not(.fr-accordion__btn):hover,
.ec-tab-panels.ol-control .ec-tab-panels__panel-body button:not(.fr-accordion__btn):focus,
.ec-tab-panels.ol-control .ec-tab-panels__panel-body button:not(.fr-accordion__btn):focus-visible {
  outline: none !important;
}

.ec-tab-panels.ol-control
  .ec-tab-panels__panel-body
  button:not(.ec-layer-catalogue__tab):not(.ec-data-layers__legend-btn):not(
    .fr-accordion__btn
  ):hover,
.ec-tab-panels.ol-control
  .ec-tab-panels__panel-body
  button:not(.ec-layer-catalogue__tab):not(.ec-data-layers__legend-btn):not(
    .fr-accordion__btn
  ):focus,
.ec-tab-panels.ol-control
  .ec-tab-panels__panel-body
  button:not(.ec-layer-catalogue__tab):not(.ec-data-layers__legend-btn):not(
    .fr-accordion__btn
  ):focus-visible {
  box-shadow: none !important;
  border: none !important;
}

.ec-tab-panels.ol-control .ec-tab-panels__panel-body .fr-btn:not(.ec-data-layers__legend-btn):hover,
.ec-tab-panels.ol-control .ec-tab-panels__panel-body .fr-btn:not(.ec-data-layers__legend-btn):focus,
.ec-tab-panels.ol-control
  .ec-tab-panels__panel-body
  .fr-btn:not(.ec-data-layers__legend-btn):focus-visible {
  outline: none !important;
  box-shadow: none !important;
  border: none !important;
  background-color: transparent !important;
  background-image: none !important;
}

.ec-tab-panels.ol-control .ec-tab-panels__panel-body img:hover,
.ec-tab-panels.ol-control .ec-tab-panels__panel-body img:focus,
.ec-tab-panels.ol-control .ec-tab-panels__panel-body img:focus-visible {
  outline: none !important;
  box-shadow: none !important;
}

.ec-tab-panels__pane[hidden] {
  display: none !important;
}

.ec-tab-panels__pane:not([hidden]) {
  display: flex;
  flex-direction: column;
  min-height: 0;
  max-width: 100%;
}

/* Fiche info — bandeau bleu + pictogramme i (capture / Figma) */
.ec-fiche-info {
  position: relative;
  padding-left: 0.25rem;
}

.ec-fiche-info__rail {
  position: absolute;
  top: 0;
  left: 0;
  width: 0.25rem;
  height: 100%;
  min-height: 4rem;
  background: var(--background-action-high-blue-france, #000091);
  border-radius: 0.125rem;
}

.ec-fiche-info__rail::after {
  content: 'i';
  position: absolute;
  top: 0.75rem;
  left: 50%;
  transform: translate(-50%, 0);
  width: 1.25rem;
  height: 1.25rem;
  margin-left: 0;
  border-radius: 50%;
  background: var(--background-default-grey, #fff);
  color: var(--text-action-high-blue-france, #000091);
  font:
    700 0.75rem/1.25rem Marianne,
    arial,
    sans-serif;
  text-align: center;
  box-shadow: 0 0 0 2px var(--background-action-high-blue-france, #000091);
}

.ec-fiche-info__inner {
  padding-left: 1.5rem;
}

.ec-fiche-info__title {
  margin: 0 0 0.75rem;
  font-size: 1.25rem;
  line-height: 1.4;
  color: var(--text-title-grey, #161616);
}

.ec-fiche-info__body {
  margin: 0;
  font-size: 0.875rem;
  line-height: 1.5;
  color: var(--text-default-grey, #161616);
}

.ec-fiche-info__body p {
  margin: 0 0 0.75rem;
}

.ec-fiche-info__body p:last-child {
  margin-bottom: 0;
}

.ec-tab-panels__empty {
  margin: 0;
  color: var(--text-mention-grey, #666);
  font-size: 0.875rem;
}

.ec-raw-info__title {
  margin: 0 0 1rem;
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.ec-raw-info__placeholder,
.ec-raw-info__list {
  margin: 0;
  padding: 1rem;
  background: var(--background-alt-grey, #f6f6f6);
  border-radius: 0.25rem;
  font-size: 0.875rem;
}

.ec-raw-info__list {
  list-style: none;
}

.ec-raw-info__list li {
  display: flex;
  gap: 0.5rem;
  padding: 0.35rem 0;
  border-bottom: 1px solid var(--border-default-grey, #ddd);
}

.ec-raw-info__list li:last-child {
  border-bottom: none;
}

.ec-raw-info__key {
  flex: 0 0 40%;
  font-weight: 700;
  word-break: break-word;
}

.ec-raw-info__val {
  flex: 1 1 auto;
  word-break: break-word;
}
/** Plan IGN NB — même tuile, rendu gris (équivalent gpu-client `grayscale: true`). */
.ec-gpu-layer-grayscale {
  filter: grayscale(100%);
}
:root,
:host {
  --ol-background-color: white;
  --ol-accent-background-color: #F5F5F5;
  --ol-subtle-background-color: rgba(128, 128, 128, 0.25);
  --ol-partial-background-color: rgba(255, 255, 255, 0.75);
  --ol-foreground-color: #333333;
  --ol-subtle-foreground-color: #666666;
  --ol-brand-color: #00AAFF;
}

.ol-box {
  box-sizing: border-box;
  border-radius: 2px;
  border: 1.5px solid var(--ol-background-color);
  background-color: var(--ol-partial-background-color);
}

.ol-mouse-position {
  top: 8px;
  right: 8px;
  position: absolute;
}

.ol-scale-line {
  background: var(--ol-partial-background-color);
  border-radius: 4px;
  bottom: 8px;
  left: 8px;
  padding: 2px;
  position: absolute;
}

.ol-scale-line-inner {
  border: 1px solid var(--ol-subtle-foreground-color);
  border-top: none;
  color: var(--ol-foreground-color);
  font-size: 10px;
  text-align: center;
  margin: 1px;
  will-change: contents, width;
  transition: all 0.25s;
}

.ol-scale-bar {
  position: absolute;
  bottom: 8px;
  left: 8px;
}

.ol-scale-bar-inner {
  display: flex;
}

.ol-scale-step-marker {
  width: 1px;
  height: 15px;
  background-color: var(--ol-foreground-color);
  float: right;
  z-index: 10;
}

.ol-scale-step-text {
  position: absolute;
  bottom: -5px;
  font-size: 10px;
  z-index: 11;
  color: var(--ol-foreground-color);
  text-shadow: -1.5px 0 var(--ol-partial-background-color), 0 1.5px var(--ol-partial-background-color), 1.5px 0 var(--ol-partial-background-color), 0 -1.5px var(--ol-partial-background-color);
}

.ol-scale-text {
  position: absolute;
  font-size: 12px;
  text-align: center;
  bottom: 25px;
  color: var(--ol-foreground-color);
  text-shadow: -1.5px 0 var(--ol-partial-background-color), 0 1.5px var(--ol-partial-background-color), 1.5px 0 var(--ol-partial-background-color), 0 -1.5px var(--ol-partial-background-color);
}

.ol-scale-singlebar {
  position: relative;
  height: 10px;
  z-index: 9;
  box-sizing: border-box;
  border: 1px solid var(--ol-foreground-color);
}

.ol-scale-singlebar-even {
  background-color: var(--ol-subtle-foreground-color);
}

.ol-scale-singlebar-odd {
  background-color: var(--ol-background-color);
}

.ol-unsupported {
  display: none;
}

.ol-viewport,
.ol-unselectable {
  -webkit-touch-callout: none;
  -webkit-user-select: none;
  -moz-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.ol-viewport canvas {
  all: unset;
  overflow: hidden;
}

.ol-viewport {
  touch-action: pan-x pan-y;
}

.ol-selectable {
  -webkit-touch-callout: default;
  -webkit-user-select: text;
  -moz-user-select: text;
  user-select: text;
}

.ol-grabbing {
  cursor: -webkit-grabbing;
  cursor: -moz-grabbing;
  cursor: grabbing;
}

.ol-grab {
  cursor: move;
  cursor: -webkit-grab;
  cursor: -moz-grab;
  cursor: grab;
}

.ol-control {
  position: absolute;
  background-color: var(--ol-subtle-background-color);
  border-radius: 4px;
}

.ol-zoom {
  top: .5em;
  left: .5em;
}

.ol-rotate {
  top: .5em;
  right: .5em;
  transition: opacity .25s linear, visibility 0s linear;
}

.ol-rotate.ol-hidden {
  opacity: 0;
  visibility: hidden;
  transition: opacity .25s linear, visibility 0s linear .25s;
}

.ol-zoom-extent {
  top: 4.643em;
  left: .5em;
}

.ol-full-screen {
  right: .5em;
  top: .5em;
}

.ol-control button {
  display: block;
  margin: 1px;
  padding: 0;
  color: var(--ol-subtle-foreground-color);
  font-weight: bold;
  text-decoration: none;
  font-size: inherit;
  text-align: center;
  height: 1.375em;
  width: 1.375em;
  line-height: .4em;
  background-color: var(--ol-background-color);
  border: none;
  border-radius: 2px;
}

.ol-control button::-moz-focus-inner {
  border: none;
  padding: 0;
}

.ol-zoom-extent button {
  line-height: 1.4em;
}

.ol-compass {
  display: block;
  font-weight: normal;
  will-change: transform;
}

.ol-touch .ol-control button {
  font-size: 1.5em;
}

.ol-touch .ol-zoom-extent {
  top: 5.5em;
}

.ol-control button:hover,
.ol-control button:focus {
  text-decoration: none;
  outline: 1px solid var(--ol-subtle-foreground-color);
  color: var(--ol-foreground-color);
}

.ol-zoom .ol-zoom-in {
  border-radius: 2px 2px 0 0;
}

.ol-zoom .ol-zoom-out {
  border-radius: 0 0 2px 2px;
}

.ol-attribution {
  text-align: right;
  bottom: .5em;
  right: .5em;
  max-width: calc(100% - 1.3em);
  display: flex;
  flex-flow: row-reverse;
  align-items: center;
}

.ol-attribution a {
  color: var(--ol-subtle-foreground-color);
  text-decoration: none;
}

.ol-attribution ul {
  margin: 0;
  padding: 1px .5em;
  color: var(--ol-foreground-color);
  text-shadow: 0 0 2px var(--ol-background-color);
  font-size: 12px;
}

.ol-attribution li {
  display: inline;
  list-style: none;
}

.ol-attribution li:not(:last-child):after {
  content: " ";
}

.ol-attribution img {
  max-height: 2em;
  max-width: inherit;
  vertical-align: middle;
}

.ol-attribution button {
  flex-shrink: 0;
}

.ol-attribution.ol-collapsed ul {
  display: none;
}

.ol-attribution:not(.ol-collapsed) {
  background: var(--ol-partial-background-color);
}

.ol-attribution.ol-uncollapsible {
  bottom: 0;
  right: 0;
  border-radius: 4px 0 0;
}

.ol-attribution.ol-uncollapsible img {
  margin-top: -.2em;
  max-height: 1.6em;
}

.ol-attribution.ol-uncollapsible button {
  display: none;
}

.ol-zoomslider {
  top: 4.5em;
  left: .5em;
  height: 200px;
}

.ol-zoomslider button {
  position: relative;
  height: 10px;
}

.ol-touch .ol-zoomslider {
  top: 5.5em;
}

.ol-overviewmap {
  left: 0.5em;
  bottom: 0.5em;
}

.ol-overviewmap.ol-uncollapsible {
  bottom: 0;
  left: 0;
  border-radius: 0 4px 0 0;
}

.ol-overviewmap .ol-overviewmap-map,
.ol-overviewmap button {
  display: block;
}

.ol-overviewmap .ol-overviewmap-map {
  border: 1px solid var(--ol-subtle-foreground-color);
  height: 150px;
  width: 150px;
}

.ol-overviewmap:not(.ol-collapsed) button {
  bottom: 0;
  left: 0;
  position: absolute;
}

.ol-overviewmap.ol-collapsed .ol-overviewmap-map,
.ol-overviewmap.ol-uncollapsible button {
  display: none;
}

.ol-overviewmap:not(.ol-collapsed) {
  background: var(--ol-subtle-background-color);
}

.ol-overviewmap-box {
  border: 1.5px dotted var(--ol-subtle-foreground-color);
}

.ol-overviewmap .ol-overviewmap-box:hover {
  cursor: move;
}

.ol-overviewmap .ol-viewport:hover {
  cursor: pointer;
}
