dth='24'%20height='24'%3e%3cpath%20d='M10.5%2017H4v-2h6.5a3.5%203.5%200%201%201-3.278%204.73l1.873-.703A1.5%201.5%200%201%200%2010.5%2017ZM5%2011h13.5a3.5%203.5%200%201%201-3.278%204.73l1.873-.703A1.5%201.5%200%201%200%2018.5%2013H5a3%203%200%201%201%200-6h8.5a1.5%201.5%200%201%200-1.405-2.027l-1.873-.702A3.501%203.501%200%200%201%2017%205.5%203.5%203.5%200%200%201%2013.5%209H5a1%201%200%200%200%200%202Z'/%3e%3c/svg%3e")}.fr-fi-flashlight-fill:before{background-image:url("data:image/svg+xml,%3csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2024%2024'%20width='24'%20height='24'%3e%3cpath%20d='M13%2010h7l-9%2013v-9H4l9-13v9Z'/%3e%3c/svg%3e")}.fr-fi-flashlight-line:before{background-image:url("data:image/svg+xml,%3csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2024%2024'%20width='24'%20height='24'%3e%3cpath%20d='M13%200v9h8L11%2024v-9H4l9-15Zm-2%207.22L7.532%2013H13v4.394L17.263%2011H11V7.22Z'/%3e%3c/svg%3e")}}/**
 * Placement des contrôles — référence :
 * https://cartes.gouv.fr/explorer-les-cartes/
 * (clone local : cartes.gouv.fr-entree-carto)
 */

:root {
  --ec-widget-gap: 8px;
  --ec-widget-btn-size: 48px;
  --ec-widget-btn-padding: 4px;
  --ec-widget-btn-radius: 4px;
  /** Colonne outils croquis (largeur layout, infobulles en overflow) */
  --ec-sketch-column-width: var(--ec-widget-btn-size);
  /** Décalage horizontal recherche lieu (évite chevauchement colonne croquis) */
  --ec-search-left-inset: 0px;
  --ec-widget-panel-x: calc(var(--ec-widget-btn-size) + var(--ec-widget-gap) * 2);
  /* Largeur panneau TabPanels (1,5 × ~408px Figma) ; inset = panneau seul
     (les onglets sont en haut : pas de reserve en bas à côté du panneau) */
  --ec-tab-panels-width: min(30.6rem, 92vw);
  --ec-tab-panels-inset: var(--ec-tab-panels-width);
  --ec-attribution-logo-width: 52px;
  --ec-attribution-logo-height: 56px;
  /** Hauteur utile du bandeau attributions (logos + padding images). */
  --ec-attribution-block-height: calc(var(--ec-attribution-logo-height) + 8px);
  /** Marge entre bandeau attributions et barre d’échelle (empilés). */
  --ec-scale-attribution-stack-gap: 6px;
}

.position {
  z-index: 1;
  width: var(--ec-widget-btn-size);
  gap: var(--ec-widget-gap);
}

/*
 * Le widget redevient containing block : PositionFactory met position:unset,
 * donc les dialog.gpf-panel se calaient sur .position (pleine hauteur) → haut de carte.
 */
.position > .gpf-widget,
.position > .gpf-widget-button {
  position: relative !important;
}

/* Panneaux : bas-gauche / bas-droite alignés sur le bas du bouton (pas top:0 inline geopf) */
.position-container-bottom-left > .gpf-widget > dialog.gpf-panel,
.position-container-bottom-left > .gpf-widget-button > dialog.gpf-panel,
.position-container-bottom-right > .gpf-widget > dialog.gpf-panel,
.position-container-bottom-right > .gpf-widget-button > dialog.gpf-panel {
  top: auto !important;
  bottom: 0 !important;
  /* reste dans la carte : ancré en bas, hauteur max = hauteur carte */
  max-height: calc(100cqb - var(--ec-widget-gap) * 2) !important;
  /* pas overflow:hidden ici : le dialog vues (left:100%) serait clipé */
}

.position-container-bottom-left > .gpf-widget > dialog.gpf-panel,
.position-container-bottom-left > .gpf-widget-button > dialog.gpf-panel {
  left: calc(var(--ec-widget-btn-size) + var(--ec-widget-gap)) !important;
}

.position-container-bottom-right > .gpf-widget > dialog.gpf-panel,
.position-container-bottom-right > .gpf-widget-button > dialog.gpf-panel {
  right: calc(var(--ec-widget-btn-size) + var(--ec-widget-gap)) !important;
}

.position-container-bottom-left > .gpf-widget > button[aria-pressed='true'] + dialog.gpf-panel,
.position-container-bottom-left
  > .gpf-widget-button
  > button[aria-pressed='true']
  + dialog.gpf-panel,
.position-container-bottom-right > .gpf-widget > button[aria-pressed='true'] + dialog.gpf-panel,
.position-container-bottom-right
  > .gpf-widget-button
  > button[aria-pressed='true']
  + dialog.gpf-panel {
  display: flex;
  flex-direction: column;
}

.position-container-top-left > .gpf-widget > dialog.gpf-panel,
.position-container-top-left > .gpf-widget-button > dialog.gpf-panel {
  top: 0 !important;
  left: calc(var(--ec-widget-btn-size) + var(--ec-widget-gap)) !important;
}

.position-container-top-right > .gpf-widget > dialog.gpf-panel,
.position-container-top-right > .gpf-widget-button > dialog.gpf-panel {
  top: 0 !important;
  right: calc(var(--ec-widget-btn-size) + var(--ec-widget-gap)) !important;
}

.position-container-top-left {
  top: var(--ec-widget-gap);
  left: var(--ec-widget-gap);
}

.position-container-bottom-left {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: var(--ec-widget-gap);
  bottom: var(--ec-widget-gap);
  left: var(--ec-widget-gap);
}

/* Infobulles croquis : ne pas clipper la colonne (padding toolbar en overflow) */
.position-container-bottom-left:has(> .ec-sketch-control--geopf-slot) {
  overflow: visible;
}

.position-container-bottom-right {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: var(--ec-widget-gap);
  bottom: var(--ec-widget-gap);
  right: var(--ec-bottom-right-inset);
  z-index: 0;
}

/* Annule les offsets geopf (top/bottom: 0.5em) qui décalent les boutons dans la colonne */
.position-container-bottom-right [id^='GPzoom-'] {
  top: 0;
  left: auto;
}

.position-container-bottom-right [id^='GPfullScreen-'] {
  /* geopf : bottom: 0.5em → remonte le bouton ; on aligne sur le bas (échelle) */
  bottom: 0;
  left: auto;
}

/* Boutons geopf : état actif = fond bleu (cartes.gouv), pas la barre ::after */
.gpf-widget-button {
  width: var(--ec-widget-btn-size);
  padding: 0;
  border-radius: var(--ec-widget-btn-radius);
  box-shadow: var(--raised-shadow, 0 2px 6px rgba(0, 0, 18, 0.16));
}

.gpf-widget-button > .gpf-btn-icon {
  width: var(--ec-widget-btn-size);
  height: var(--ec-widget-btn-size);
  padding: var(--ec-widget-btn-padding);
  filter: none;
  max-width: initial !important;
  max-height: initial !important;
  background-color: var(--background-default-grey, #fff);
  box-shadow: inset 0 0 0 var(--ec-widget-btn-padding) var(--background-default-grey, #fff);
  transition: background-color 300ms;
}

.gpf-widget-button > .gpf-btn-icon:not(:disabled):hover {
  background-color: var(--hover-tint, #e3e3fd);
}

.gpf-widget-button > .gpf-btn-icon[aria-pressed='true'],
.gpf-widget-button > .gpf-btn-icon[aria-pressed='true']:not(:disabled):hover,
.gpf-widget > .gpf-btn-icon[aria-pressed='true'],
.gpf-widget > .gpf-btn-icon[aria-pressed='true']:not(:disabled):hover {
  background-color: var(--background-open-blue-france, #e3e3fd);
}

.gpf-widget-button:has(> .gpf-btn-icon[aria-pressed='true'])::after,
.gpf-widget:has(> .gpf-btn-icon[aria-pressed='true'])::after {
  content: none;
}

/* Infobulles — appendice aligné sur le bord du bouton (cartes.gouv Controls.vue) */
.position-container-top-left > .gpf-widget-button > .gpf-btn-icon[aria-label]:hover::before,
.position-container-bottom-left > .gpf-widget-button > .gpf-btn-icon[aria-label]:hover::before,
.position-container-top-left > .gpf-widget > .gpf-btn-icon[aria-label]:hover::before,
.position-container-bottom-left > .gpf-widget > .gpf-btn-icon[aria-label]:hover::before {
  transform: translate(
    calc(var(--ec-widget-btn-size) - var(--ec-widget-btn-padding) * 2),
    var(--ec-widget-btn-padding)
  );
}

.position-container-top-right > .gpf-widget-button > .gpf-btn-icon[aria-label]:hover::before,
.position-container-bottom-right > .gpf-widget-button > .gpf-btn-icon[aria-label]:hover::before,
.position-container-top-right > .gpf-widget > .gpf-btn-icon[aria-label]:hover::before,
.position-container-bottom-right > .gpf-widget > .gpf-btn-icon[aria-label]:hover::before {
  transform: translate(-100%, var(--ec-widget-btn-padding));
}

.position:has(> .gpf-widget-button > .gpf-btn-icon[aria-label]:hover),
.position:has(> .gpf-widget > .gpf-btn-icon[aria-label]:hover),
.position:has(> .ec-sketch-control .ec-geometry-editor__tool[aria-label]:hover) {
  z-index: 3;
}

.position > .gpf-widget-button > .gpf-btn-icon[aria-pressed='true']:hover::before,
.position > .gpf-widget > .gpf-btn-icon[aria-pressed='true']:hover::before {
  content: none;
}

/* Minimap au-dessus du sélecteur de territoire (cartes.gouv OverviewMap.vue) */
.position-container-bottom-left > .gpf-widget[id^='GPoverviewMap-'] {
  order: -1;
  position: relative !important;
  left: auto;
  bottom: auto;
}

/* SketchControl : slot geopf uniquement (styles boutons = geometry-editor.css) */
.position-container-bottom-left > .ec-sketch-control--geopf-slot {
  order: -2;
  position: relative !important;
  inset: auto !important;
  top: auto !important;
  right: auto !important;
  bottom: auto !important;
  left: auto !important;
  margin: 0;
  align-self: flex-start;
  flex: 0 1 auto;
  /* Colonne 48px ; infobulles croquis en overflow visible */
  overflow: visible;
  width: var(--ec-sketch-column-width);
  max-width: var(--ec-sketch-column-width);
  /*
   * Hauteur bornée à la carte (cqb) : réserve minimap (~2 boutons) + gaps.
   */
  max-height: calc(
    100cqb - 2 * var(--ec-widget-gap) - (var(--ec-widget-btn-size) * 2 + var(--ec-widget-gap) * 2)
  );
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: var(--ec-widget-gap);
}

/*
 * Toolbar : colonne layout 48px, zone infobulle à droite (comme geometry-editor.css).
 * margin-inline-end négatif → n’élargit pas la colonne geopf ; overflow-x:hidden
 * garde les bulles dans la zone padding (sinon clip avec overflow-y:auto).
 */
.position-container-bottom-left
  > .ec-sketch-control--geopf-slot
  > .ec-geometry-editor__toolbar-cluster {
  flex: 1 1 auto;
  min-height: 0;
  max-height: 100%;
  margin-inline-end: calc(-1 * var(--ec-geom-tooltip-space));
}

.position-container-bottom-left
  > .ec-sketch-control--geopf-slot
  > .ec-geometry-editor__toolbar-cluster
  > .ec-geometry-editor__toolbar {
  --ec-geom-tooltip-space: 12.5rem;
  flex: 1 1 auto;
  box-sizing: border-box;
  width: calc(var(--ec-sketch-column-width) + var(--ec-geom-tooltip-space));
  max-width: none;
  min-height: 0;
  max-height: 100%;
  padding-inline-end: var(--ec-geom-tooltip-space);
  overflow-x: hidden;
  overflow-y: auto;
}

.position-container-bottom-left > .ec-sketch-control--geopf-slot .ec-geometry-editor__tool {
  overflow: visible;
}

.position-container-bottom-left
  > .ec-sketch-control--geopf-slot[data-corner]
  > .ec-geometry-editor__toolbar-cluster {
  /* Place pour le bouton menu toolsToggle */
  max-height: calc(100% - var(--ec-widget-btn-size) - var(--ec-widget-gap));
}

.position-container-bottom-left:has(
  > .ec-sketch-control--geopf-slot .ec-geometry-editor__tool[aria-label]:hover
),
.position-container-top-left:has(
  > .ec-sketch-control--geopf-slot .ec-geometry-editor__tool[aria-label]:hover
) {
  z-index: 3;
  overflow: visible;
}

.position-container-bottom-left > .gpf-widget[id^='GPoverviewMap-'] .ol-overviewmap-map {
  position: absolute;
  top: 0;
  left: calc(var(--ec-widget-btn-size) + var(--ec-widget-gap));
  border-radius: 4px;
  width: calc(var(--ec-widget-btn-size) * 2 + var(--ec-widget-gap));
  height: calc(var(--ec-widget-btn-size) * 2 + var(--ec-widget-gap));
  border: solid 4px var(--background-default-grey, #fff);
  background-color: var(--background-default-grey, #fff);
}

/* Croquis présent → réserve la colonne gauche pour la barre outils */
.ec-map-shell:has(.ec-sketch-control--geopf-slot) {
  --ec-search-left-inset: calc(var(--ec-sketch-column-width) + var(--ec-widget-gap));
}

/* SearchEngine — haut-gauche (cartes.gouv SearchEngine.vue) */
.gpf-widget[id^='GPsearchEngine-Advanced'] {
  top: var(--ec-widget-gap);
  left: calc(var(--ec-widget-gap) - 5px + var(--ec-search-left-inset));
  z-index: 1;
  box-shadow: none;
  max-width: min(420px, calc(100% - 12px - var(--ec-search-left-inset)));
}

/*
 * Popup résultat SearchEngineAdvanced : l’appendice (::before bordure + ::after fond)
 * laisse parfois un trait gris (bordure basse de la bulle) entre bulle et pointe.
 * On aligne ::after pour couvrir ce pixel ; marges <p> neutralisées (contenu HTML).
 */
.ec-map-shell .GPSearchPopup::after {
  bottom: -16px;
  border-top-width: 16px;
}

.ec-map-shell .GPPopupContent p {
  margin: 0;
}

.ec-map-shell .GPPopupContent p + p {
  margin-top: 0.25rem;
}

.gpf-widget[id^='GPsearchEngine-Advanced'] .GPSearchBar .GPInputGroup,
.gpf-widget[id^='GPsearchEngine-Advanced'] .GPSearchBar .GPInputGroup > input,
.gpf-widget[id^='GPsearchEngine-Advanced'] button[id^='GPshowSearchEnginePicto-'].fr-btn {
  height: var(--ec-widget-btn-size);
}

.GPsearchInputSubmit {
  flex: 0 0 var(--ec-widget-btn-size);
}

.GPsearchInputSubmit::before {
  margin: 0 auto !important;
}

/*
 * Doublon d’icônes (surtout sous gpu-site / DSFR hôte) :
 * geopf pose une couche picto sur ::after (width/height: 100 % du bouton) ;
 * les classes DSFR fr-icon-* appliquent le même mask sur ::before et ::after.
 * → grande icône (::after) + petite (::before). On garde uniquement ::before.
 * Les boutons sans fr-icon-* (zoom, fullscreen, search…) continuent d’utiliser ::after.
 */
.gpf-btn--primary[class*='fr-icon-']::after,
.gpf-btn--secondary[class*='fr-icon-']::after,
.gpf-btn--tertiary[class*='fr-icon-']::after,
.gpf-btn[class*='fr-icon-']::after {
  content: none !important;
  mask: none !important;
  -webkit-mask: none !important;
  background: none !important;
  width: 0 !important;
  height: 0 !important;
}

/* Plein écran : icône uniquement via ::after geopf (pas de sprite / label OL) */
.ol-custom-full-screen button.gpf-btn-icon {
  background-image: none !important;
  font-size: 0;
  line-height: 0;
}

.ol-custom-full-screen button.gpf-btn-icon > span {
  display: none;
}

/*
 * Infobulle plein écran : le bouton a font-size:0 (masquer le label OL),
 * la bulle ::before doit retrouver la taille des autres contrôles.
 */
.ol-custom-full-screen button.gpf-btn-icon[aria-label]:hover::before,
.ol-custom-full-screen button.gpf-btn-icon[aria-label]:focus:focus-visible::before {
  font-size: 0.75rem;
  line-height: 1.25;
}

/* Territories — titres longs dans les tuiles */
.gpf-tile .fr-tile__title,
.gpf-tile .fr-tile__title .fr-label {
  font-size: 0.75rem;
  line-height: 1.25;
  overflow: hidden;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  word-break: break-word;
  hyphens: auto;
}

/* Territories — header : fermer absolument à droite (geopf #GPterritoriesPanelClose) */
dialog[id^='GPterritoriesPanel-'] > .gpf-panel__header,
dialog[id^='GPterritoriesPanel-'] > .GPpanelHeader {
  position: relative;
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  width: 100%;
  box-sizing: border-box;
  padding-right: 2.75rem;
}

dialog[id^='GPterritoriesPanel-'] .gpf-panel__title,
dialog[id^='GPterritoriesPanel-'] .GPpanelTitle {
  flex: 1 1 auto;
  min-width: 0;
}

#GPterritoriesPanelClose {
  position: absolute !important;
  top: 50% !important;
  right: 0.25rem !important;
  left: auto !important;
  bottom: auto !important;
  transform: translateY(-50%);
  margin: 0 !important;
  z-index: 2;
}

/* Territories — corps scrollable pour ne pas sortir en haut de la carte */
dialog[id^='GPterritoriesPanel-'] > .gpf-panel__territories,
dialog[id^='GPterritoriesPanel-'] > .territories-views,
dialog[id^='GPterritoriesPanel-'] > .gpf-panel__menuviews_territories {
  flex: 0 0 auto;
}

dialog[id^='GPterritoriesPanel-'] > .territories-entries {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
}

/* Territories — dialog « Modifier les territoires » collé à droite du panneau, bas alignés */
dialog[id^='GPterritoriesPanel-'] {
  overflow: visible;
}

#gpf-territories-views-container-id {
  position: absolute;
  top: auto !important;
  bottom: 0;
  /* containing block = dialog.GPterritoriesPanel (pas le bandeau menuviews) */
  left: 100%;
  z-index: 10000;
  /* même hauteur que le panneau « Sélectionner un territoire » */
  height: 100%;
  max-height: 100%;
  /* évite le rétrécissement (width:auto → tagliatelle) : au moins la largeur du panneau */
  min-width: 100%;
  width: max-content;
  overflow: auto;
  box-sizing: border-box;
  box-shadow: var(--raised-shadow, 0 2px 6px rgba(0, 0, 18, 0.16));
  background-color: var(--background-default-grey, #fff);
}

/* geopf toggle gpf-visible ; <dialog> est display:none par défaut */
#gpf-territories-views-container-id.gpf-visible {
  display: block !important;
}

.gpf-panel__body_territories,
.gpf-panel__views_territories-listview-entries {
  max-height: initial;
}

/*
 * Bas-droite : colonne widgets (.position-container-bottom-right),
 * attributions en bas (ancrage horizontal de l’ancienne échelle),
 * barre d’échelle juste au-dessus avec une petite marge.
 */
.ec-map-shell {
  --ec-bottom-right-inset: var(--ec-widget-gap);
  --ec-scale-line-right: calc(
    var(--ec-bottom-right-inset) + var(--ec-widget-btn-size) + var(--ec-widget-gap)
  );
}

.ec-map-shell--tab-panels-open {
  --ec-bottom-right-inset: calc(var(--ec-widget-gap) + var(--ec-tab-panels-inset));
}

#gpu-map .ol-control.ol-attribution {
  left: auto;
  right: var(--ec-scale-line-right);
  bottom: var(--ec-widget-gap);
  background-color: transparent;
  max-width: none;
}

#gpu-map .ol-attribution.ol-uncollapsible {
  bottom: var(--ec-widget-gap);
}

.ol-scale-line {
  z-index: auto;
  left: auto;
  right: var(--ec-scale-line-right);
  bottom: calc(
    var(--ec-widget-gap) + var(--ec-attribution-block-height) +
      var(--ec-scale-attribution-stack-gap)
  );
  background: var(--background-default-grey, #fff);
}

#gpu-map .ol-attribution ul {
  display: flex;
  flex-flow: row nowrap;
  align-items: flex-end;
  justify-content: flex-end;
  gap: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

#gpu-map .ol-attribution li {
  display: inline-flex;
  align-items: flex-end;
  margin: 0;
  padding: 0;
}

#gpu-map .ol-attribution li:not(:last-child)::after {
  content: none;
}

#gpu-map .ol-attribution img.map-logo-ign-svg,
#gpu-map .ol-attribution img.map-logo-ministere-svg {
  display: block;
  width: var(--ec-attribution-logo-width);
  height: var(--ec-attribution-logo-height);
  object-fit: contain;
  box-sizing: border-box;
  margin: 0;
  max-height: none;
  background-color: white !important;
  padding: 4px;
}

/* Pas d’icône « lien externe » DSFR sur les logos */
#gpu-map .ol-attribution a:has(img)[target='_blank']::after {
  content: none !important;
  mask-image: none !important;
  -webkit-mask-image: none !important;
  background: none !important;
}

#gpu-map .ol-attribution a.legal-attribution {
  display: inline-flex;
  align-items: flex-end;
  white-space: nowrap;
  text-decoration: none;
  font-size: 14px;
  line-height: 1.15;
  margin-right: 6px;
  padding-bottom: 2px;
  color: black;
  font-weight: bold;
}

#gpu-map .ol-attribution a.legal-attribution:hover,
#gpu-map .ol-attribution a.legal-attribution:focus {
  text-decoration: none;
}
/* SearchEngineAdvanced monté hors carte (accueil gpu-site / démo). */

.ec-search-engine-standalone {
