  order: 1;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  border-radius: 0 !important;
}

.ec-search-engine-standalone form.GPSearchBar .GPsearchInputText,
.ec-search-engine-standalone form.GPSearchBar .GPInputGroup > input {
